CREATE TABLE evlet_api_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, name TEXT NOT NULL, prefix TEXT NOT NULL UNIQUE, hash TEXT NOT NULL, scope TEXT NOT NULL, created_at INTEGER NOT NULL, last_used INTEGER, revoked_at INTEGER);
CREATE TABLE evlet_app_settings (app TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, changed_by INTEGER, changed_at INTEGER, PRIMARY KEY (app, key));
CREATE TABLE evlet_attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, model TEXT NOT NULL, record_id INTEGER NOT NULL, name TEXT NOT NULL, content BLOB NOT NULL, storage_key TEXT, file_size INTEGER, storage_kind TEXT, purpose TEXT, owner INTEGER, created_at INTEGER);
CREATE TABLE evlet_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor TEXT NOT NULL, area TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL, before TEXT, after TEXT);
CREATE TABLE evlet_config (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL);
INSERT INTO "evlet_config" VALUES(1,1);
CREATE TABLE evlet_connectors (id TEXT PRIMARY KEY, app TEXT NOT NULL, status TEXT NOT NULL, settings TEXT NOT NULL, secrets BLOB, changed_by TEXT, changed_at INTEGER);
CREATE TABLE evlet_custom_fields (model TEXT NOT NULL, name TEXT NOT NULL, definition TEXT NOT NULL, created_by TEXT, created_at INTEGER, PRIMARY KEY (model, name));
CREATE TABLE evlet_email_tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, new_email TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE evlet_framework_migrations (position INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, checksum TEXT NOT NULL, evlet_version TEXT NOT NULL, applied_at INTEGER NOT NULL);
