CREATE TABLE evlet_inbox (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, kind TEXT NOT NULL, actor INTEGER, model TEXT NOT NULL, record_id INTEGER NOT NULL, entry_id INTEGER, at INTEGER NOT NULL, read_at INTEGER, email TEXT, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE evlet_journal (id INTEGER PRIMARY KEY AUTOINCREMENT, model TEXT NOT NULL, record_id INTEGER NOT NULL, kind TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, data TEXT NOT NULL, prev_hash TEXT, hash TEXT);
CREATE TABLE evlet_journal_hashed (model TEXT PRIMARY KEY);
INSERT INTO "evlet_journal_hashed" VALUES('customer');
CREATE TABLE evlet_mail_links (model TEXT NOT NULL, record_id INTEGER NOT NULL, message_key TEXT NOT NULL, entry_id INTEGER NOT NULL, PRIMARY KEY (model, record_id, message_key, entry_id));
CREATE TABLE evlet_mail_states (hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, provider TEXT NOT NULL, secrets BLOB NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE evlet_mailboxes (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES evlet_users(id) ON DELETE CASCADE, provider TEXT NOT NULL, address TEXT NOT NULL, settings TEXT NOT NULL, secrets BLOB, status TEXT NOT NULL, error TEXT, cursor TEXT, linking INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, attempted_at INTEGER, synced_at INTEGER);
CREATE TABLE evlet_mcp_clients (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, oauth_client TEXT NOT NULL REFERENCES evlet_oauth_clients(id) ON DELETE CASCADE, client_name TEXT NOT NULL, created_at INTEGER NOT NULL, last_used INTEGER, calls INTEGER NOT NULL DEFAULT 0, allow_changes INTEGER NOT NULL DEFAULT 0, apps TEXT, revoked_at INTEGER);
CREATE TABLE evlet_mcp_tokens (hash TEXT PRIMARY KEY, client_id INTEGER NOT NULL REFERENCES evlet_mcp_clients(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('access','refresh')), expires INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE evlet_migrations (position INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, checksum TEXT NOT NULL);
