CREATE TABLE evlet_money (id INTEGER PRIMARY KEY CHECK(id = 1), scale INTEGER NOT NULL);
INSERT INTO "evlet_money" VALUES(1,6);
CREATE TABLE evlet_oauth_clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, redirect_uris TEXT NOT NULL, secret TEXT, auth_method TEXT NOT NULL DEFAULT 'none' CHECK(auth_method IN ('none','client_secret_post','client_secret_basic')), created_at INTEGER NOT NULL);
CREATE TABLE evlet_oauth_codes (hash TEXT PRIMARY KEY, oauth_client TEXT NOT NULL REFERENCES evlet_oauth_clients(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, redirect_uri TEXT NOT NULL, challenge TEXT NOT NULL, allow_changes INTEGER NOT NULL, expires INTEGER NOT NULL, grant_id INTEGER);
CREATE TABLE evlet_overrides (kind TEXT NOT NULL CHECK(kind IN ('perm','field','custom','layout','list','naming','setting','workspace')), key TEXT NOT NULL, value TEXT NOT NULL, changed_by INTEGER, changed_at INTEGER, PRIMARY KEY (kind, key));
CREATE TABLE evlet_period_locks (scope TEXT PRIMARY KEY, lock_date TEXT NOT NULL, changed_by INTEGER, changed_at INTEGER NOT NULL);
CREATE TABLE evlet_print_designs (name TEXT PRIMARY KEY, definition TEXT NOT NULL, changed_by TEXT, changed_at INTEGER);
CREATE TABLE evlet_retired_fields (model TEXT NOT NULL, name TEXT NOT NULL, definition TEXT NOT NULL, PRIMARY KEY (model, name));
