CREATE TABLE evlet_sections (id INTEGER PRIMARY KEY, collection TEXT NOT NULL, owner INTEGER NOT NULL, position INTEGER NOT NULL, label TEXT NOT NULL);
CREATE TABLE evlet_tool_approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, origin TEXT NOT NULL, client TEXT, run_id INTEGER, tool TEXT NOT NULL, arguments TEXT NOT NULL, digest TEXT NOT NULL, summary TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','declined','used','expired')), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, decided_at INTEGER);
CREATE TABLE evlet_unsaved (user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, model TEXT NOT NULL, record_id INTEGER NOT NULL, changes TEXT NOT NULL, base_revision TEXT NOT NULL, saved_at INTEGER NOT NULL, size INTEGER NOT NULL, PRIMARY KEY (user_id, model, record_id));
CREATE TABLE evlet_user_links (user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, model TEXT NOT NULL, record_id INTEGER NOT NULL, PRIMARY KEY (user_id, model, record_id));
CREATE TABLE evlet_user_prefs (user_id INTEGER NOT NULL REFERENCES evlet_users(id) ON DELETE CASCADE, scope TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY (user_id, scope, key));
CREATE TABLE evlet_user_profile (user_id INTEGER PRIMARY KEY REFERENCES evlet_users(id) ON DELETE CASCADE, full_name TEXT NOT NULL DEFAULT '', short_name TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', photo_file INTEGER, signature TEXT NOT NULL DEFAULT '', two_step_secret BLOB, backup_codes TEXT, two_step_since INTEGER, two_step_last INTEGER, two_step_pending BLOB, two_step_agent TEXT NOT NULL DEFAULT '');
