CREATE UNIQUE INDEX "evlet_customer_name_unique" ON "customer" ("name");
CREATE TRIGGER "evlet_customer_fixed_id" BEFORE UPDATE OF "id" ON "customer" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'customer: record ids never change'); END;
CREATE UNIQUE INDEX "evlet_invoice_name_unique" ON "invoice" ("name");
CREATE TRIGGER "evlet_invoice_fixed_id" BEFORE UPDATE OF "id" ON "invoice" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'invoice: record ids never change'); END;
CREATE INDEX "evlet_move_invoice_index" ON "move" ("invoice");
CREATE TRIGGER "evlet_move_no_update" BEFORE UPDATE ON "move" BEGIN SELECT RAISE(ABORT, 'move is append only'); END;
CREATE TRIGGER "evlet_move_no_delete" BEFORE DELETE ON "move" BEGIN SELECT RAISE(ABORT, 'move is append only'); END;
CREATE TRIGGER "evlet_move_no_replace" BEFORE INSERT ON "move" WHEN EXISTS (SELECT 1 FROM "move" WHERE "id" = NEW."id") BEGIN SELECT RAISE(ABORT, 'move is append only'); END;
CREATE TRIGGER "evlet_move_fixed_id" BEFORE UPDATE OF "id" ON "move" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'move: record ids never change'); END;
CREATE INDEX "evlet_invoice_issued_index" ON "invoice" ("issued");
CREATE INDEX evlet_api_key_user ON evlet_api_keys(user_id);
CREATE INDEX evlet_mcp_client_user ON evlet_mcp_clients(user_id);
CREATE INDEX evlet_mcp_token_client ON evlet_mcp_tokens(client_id);
CREATE TRIGGER evlet_audit_no_update BEFORE UPDATE ON evlet_audit BEGIN SELECT RAISE(ABORT, 'The audit log is append-only'); END;
CREATE TRIGGER evlet_audit_no_delete BEFORE DELETE ON evlet_audit BEGIN SELECT RAISE(ABORT, 'The audit log is append-only'); END;
CREATE TRIGGER evlet_audit_no_replace BEFORE INSERT ON evlet_audit WHEN EXISTS (SELECT 1 FROM evlet_audit WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT, 'The audit log is append-only'); END;
CREATE INDEX evlet_tool_approval_user ON evlet_tool_approvals(user_id, status);
CREATE INDEX evlet_tool_approval_digest ON evlet_tool_approvals(digest);
CREATE INDEX evlet_mail_links_key ON evlet_mail_links(message_key);
CREATE INDEX evlet_attachment_owner ON evlet_attachments(model,record_id);
CREATE INDEX evlet_attachment_held ON evlet_attachments(purpose,record_id,created_at);
CREATE INDEX evlet_inbox_user ON evlet_inbox(user_id, hidden, read_at, id);
CREATE INDEX evlet_unsaved_saved_at ON evlet_unsaved (saved_at);
CREATE INDEX evlet_journal_record ON evlet_journal (model, record_id, id);
CREATE TRIGGER evlet_journal_no_update BEFORE UPDATE ON evlet_journal BEGIN SELECT RAISE(ABORT, 'The journal is append only'); END;
CREATE TRIGGER evlet_journal_no_delete BEFORE DELETE ON evlet_journal BEGIN SELECT RAISE(ABORT, 'The journal is append only'); END;
CREATE TRIGGER evlet_journal_no_replace BEFORE INSERT ON evlet_journal WHEN EXISTS (SELECT 1 FROM evlet_journal WHERE id = NEW.id) BEGIN SELECT RAISE(ABORT, 'The journal is append only'); END;
